<!doctype html><html lang="en"><head><meta charset="UTF-8"><title>Create Recruiter Job</title><link rel="stylesheet" href="/project/public/assets/css/style.css"></head><body><div class="container"><h2>Create Job on Behalf of Client</h2><?php if (!empty($error)): ?><div class="alert alert-error"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><form method="post" action="index.php?route=recruiter/jobs/create"><div class="grid-2"><div><label>Client</label><select name="client_id" required><option value="">Select Client</option><?php foreach ($clients as $client): ?><option value="<?php echo (int)$client['id']; ?>"><?php echo htmlspecialchars($client['company_name_override'] ?? $client['employer_company_name'] ?? ('Client #' . $client['id'])); ?></option><?php endforeach; ?></select></div><div><label>Category</label><select name="category_id" required><option value="">Select Category</option><?php foreach ($categories as $category): ?><option value="<?php echo (int)$category['id']; ?>"><?php echo htmlspecialchars($category['name']); ?></option><?php endforeach; ?></select></div></div><label>Title</label><input name="title" required><label>Description</label><textarea name="description" required></textarea><div class="grid-2"><div><label>Requirements</label><textarea name="requirements"></textarea></div><div><label>Benefits</label><textarea name="benefits"></textarea></div></div><div class="grid-2"><div><label>Salary Min</label><input name="salary_min" type="number" step="0.01"></div><div><label>Salary Max</label><input name="salary_max" type="number" step="0.01"></div></div><div class="grid-2"><div><label>Location</label><input name="location"></div><div><label>Deadline</label><input name="deadline" type="date" required></div></div><div class="grid-2"><div><label>Job Type</label><select name="job_type" required><option value="full-time">Full-time</option><option value="part-time">Part-time</option><option value="remote">Remote</option><option value="contract">Contract</option></select></div><div><label>Experience</label><select name="experience_level" required><option value="entry">Entry</option><option value="mid">Mid</option><option value="senior">Senior</option></select></div></div><label>Status</label><select name="status" required><option value="draft">Draft</option><option value="active">Active</option><option value="closed">Closed</option></select><div class="actions"><button type="submit">Create Job</button><a class="btn btn-secondary" href="index.php?route=recruiter/dashboard">Back</a></div></form></div></body></html>
